#include <string>
#include <cstdint>
struct Handler {
    uint64_t lastApplied;
    explicit Handler(uint64_t base) : lastApplied(base) {}
    // returns: "apply", "duplicate", or "gap a..b"
    std::string onMessage(uint64_t seq){
        if (seq <= lastApplied) return "duplicate";
        if (seq == lastApplied + 1){ lastApplied = seq; return "apply"; }
        return "gap " + std::to_string(lastApplied + 1) + ".." + std::to_string(seq - 1);
    }
};

class Handler:
    def __init__(self, base):
        self.last = base

    def on_message(self, seq):
        if seq <= self.last:
            return "duplicate"
        if seq == self.last + 1:
            self.last = seq
            return "apply"
        return f"gap {self.last + 1}..{seq - 1}"  # do not advance until recovered
